S = "Hakeem Force Academy"
QS = [
(S, "A train covers 20 km in 100 minutes. How long will it take to cover 1 km?", ["4 minutes", "5 minutes", "6 minutes", "10 minutes"], 1, "100 minutes divided by 20 km gives 5 minutes for each km.", "At this pace the train's speed is 12 km per hour.", [1489]),
(S, "The speed of a train is twice that of a car. If the car travels 100 km in one hour, how far does the train travel in 30 minutes?", ["50 km", "200 km", "100 km", "150 km"], 2, "Train speed is 2 x 100 = 200 km/h. In half an hour it covers 200 / 2 = 100 km.", "Distance equals speed multiplied by time.", [893]),
(S, "What is 65% of 100?", ["35", "6.5", "165", "65"], 3, "65% of 100 = 65/100 x 100 = 65.", "Percent of 100 is always the same number as the percent itself.", [619]),
(S, "Which number is different: 104, 106, 108, 110, 103?", ["104", "103", "110", "108"], 1, "104, 106, 108 and 110 are all even numbers, while 103 is odd.", "An even number is divisible by 2 with no remainder.", [1290]),
(S, "Which number is different: 103, 104, 105, 116, 106?", ["116", "103", "105", "106"], 0, "103, 104, 105 and 106 are consecutive numbers, but 116 does not fit in the sequence.", "Consecutive numbers differ by exactly 1.", [4200]),
(S, "Today is Monday and it is the 12th day of the month. What day will the 10th of the same month be?", ["Saturday", "Friday", "Sunday", "Tuesday"], 0, "The 10th is 2 days before the 12th. Two days before Monday is Saturday.", "A week has 7 days, so the same weekday repeats every 7 days.", [2034]),
(S, "What is 1/4 of 1/10 of 120?", ["12", "30", "4", "3"], 3, "1/10 of 120 = 12. Then 1/4 of 12 = 3.", "A quarter of a number is the same as dividing it by 4.", [2808, 2812, 615, 88]),
(S, "Which number comes next: 65, 115, 75, 175, ?", ["85", "95", "235", "185"], 0, "Alternate terms form two series. The 1st, 3rd and 5th terms go 65, 75, so the next is 75 + 10 = 85. The even-place terms go 115, 175.", "In alternating series, look at odd and even positions separately.", [4177]),
(S, "Which number comes next: 115, 55, 170, 65, 235, ?", ["75", "85", "310", "90"], 0, "Alternate terms form two series. The even-place terms go 55, 65, so the next is 65 + 10 = 75. The other series goes 115, 170, 235.", "The odd-place series rises by 55 then 65, so its next gap would be 75.", [4176]),
(S, "Total students are 1500 and 1300 are absent. What is the percentage of present students (approximately)?", ["86.67%", "13.33%", "20%", "15%"], 1, "Present students = 1500 - 1300 = 200. Percentage = 200/1500 x 100 = 13.33%.", "Present % plus absent % always equals 100%.", [2706]),
(S, "If the 3rd day of a month is Sunday, what day is the 12th of that month?", ["Monday", "Wednesday", "Tuesday", "Monday or Friday"], 2, "12 - 3 = 9 days later. 9 = 7 + 2, so move 2 days forward from Sunday, which is Tuesday.", "Only the remainder after dividing the gap by 7 matters.", [2026]),
(S, "If the 13th day of a month is Monday, what day is the 28th of that month?", ["Monday", "Tuesday", "Sunday", "Wednesday"], 1, "28 - 13 = 15 days later. 15 = 14 + 1, so move 1 day forward from Monday, which is Tuesday.", "Two full weeks (14 days) bring back the same weekday.", [236]),
(S, "If the 1st day of a month is Sunday, what day is the 13th of that month?", ["Thursday", "Saturday", "Friday", "Sunday"], 2, "13 - 1 = 12 days later. 12 = 7 + 5, so move 5 days forward from Sunday, which is Friday.", "Sunday plus 5 days: Mon, Tue, Wed, Thu, Fri.", [2014]),
(S, "If the 24th date of a month is Friday, what day is the 14th of that month?", ["Monday", "Wednesday", "Thursday", "Tuesday"], 3, "24 - 14 = 10 days earlier. 10 = 7 + 3, so go back 3 days from Friday: Thursday, Wednesday, Tuesday.", "Going back 3 days equals going forward 4 days in a week.", [1990]),
(S, "If the 4th day of a month is Friday, what day is the 14th of that month?", ["Sunday", "Monday", "Tuesday", "Saturday"], 1, "14 - 4 = 10 days later. 10 = 7 + 3, so move 3 days forward from Friday: Saturday, Sunday, Monday.", "The 11th and 18th would also be Monday if the 4th is Friday.", [2000]),
(S, "If the 2nd of a month is Monday, what day is the 16th of that month?", ["Tuesday", "Sunday", "Monday", "Saturday"], 2, "16 - 2 = 14 days, which is exactly two weeks, so the day is the same: Monday.", "Dates 7 apart always fall on the same weekday.", [1925, 1996]),
(S, "Find the odd one out: 150, 261, 372, 594, 695", ["150", "372", "594", "695"], 3, "The series goes up by 111: 150, 261, 372, 483, 594, then 705. The term 695 does not fit (it should be 705).", "483 is missing from the list but the 111 pattern still holds.", [1721]),
(S, "A train moves at a speed of 60 km/hour. How much time will it take to cover 150 km?", ["2 hours", "3 hours", "2.5 hours", "2.25 hours"], 2, "Time = distance / speed = 150 / 60 = 2.5 hours.", "2.5 hours equals 2 hours 30 minutes.", [167]),
(S, "Which battle was fought in 1757 between Nawab Siraj ud Daula and the British East India Company?", ["Battle of Buxar", "Battle of Panipat", "Battle of Plassey", "Battle of Seringapatam"], 2, "The Battle of Plassey was fought on 23 June 1757 in Bengal, where Robert Clive defeated Siraj ud Daula.", "Mir Jafar's betrayal helped the British win Plassey, and the Battle of Buxar followed in 1764.", [3238, 4347]),
(S, "Who was the Governor General of India during the War of Independence of 1857 and became the first Viceroy in 1858?", ["Lord Dalhousie", "Lord Canning", "Lord Curzon", "Lord Ripon"], 1, "Lord Canning was Governor General from 1856 to 1858. After the Government of India Act 1858 he became the first Viceroy.", "Lord Dalhousie was his predecessor and introduced the Doctrine of Lapse.", [4710, 4764, 4765, 4766, 4767]),
(S, "Which Muslim leader was given the title of knighthood (Sir) by the British in 1888?", ["Allama Iqbal", "Nawab Salimullah", "Sir Syed Ahmad Khan", "Aga Khan"], 2, "Sir Syed Ahmad Khan was awarded the title KCSI (Knight Commander of the Star of India) in 1888.", "Allama Iqbal was knighted later, in 1923.", [913, 4226, 4433]),
(S, "Who was the Viceroy of India in 1911 when the partition of Bengal was annulled?", ["Lord Minto", "Lord Hardinge", "Lord Curzon", "Lord Chelmsford"], 1, "Lord Hardinge was Viceroy from 1910 to 1916. The annulment of the 1905 partition was announced at the Delhi Durbar in December 1911.", "The capital was also shifted from Calcutta to Delhi in 1911.", [747, 4770, 4772, 377]),
(S, "Which reforms were introduced in British India in 1919?", ["Morley-Minto Reforms", "Montagu-Chelmsford Reforms", "Cripps Proposals", "Simon Reforms"], 1, "The Montagu-Chelmsford Reforms were enacted as the Government of India Act 1919 and introduced dyarchy in the provinces.", "The Morley-Minto Reforms were earlier, in 1909.", [4278]),
(S, "The Nehru Report of 1928 was prepared by a committee headed by whom?", ["Jawaharlal Nehru", "Motilal Nehru", "Gandhi", "Tej Bahadur Sapru"], 1, "The All Parties Committee that drafted the 1928 Nehru Report was chaired by Motilal Nehru.", "Jawaharlal Nehru, his son, served as secretary of the committee.", [4428]),
(S, "Who prepared the Pirpur Report of 1938 on the grievances of Muslims in Congress provinces?", ["Raja Syed Muhammad Mehdi of Pirpur", "Fazlul Haq", "Liaquat Ali Khan", "Chaudhry Khaliquzzaman"], 0, "The Pirpur Report was prepared by a Muslim League committee headed by Raja Syed Muhammad Mehdi of Pirpur.", "Fazlul Haq issued a separate report in 1939 called the Sharif Report.", [375, 1423, 4254]),
(S, "Who launched the Quit Kashmir Movement in 1946 against the Dogra Maharaja?", ["Chaudhry Ghulam Abbas", "Sheikh Abdullah", "Mirwaiz Yusuf Shah", "Sardar Ibrahim"], 1, "Sheikh Abdullah and his National Conference launched the Quit Kashmir Movement in May 1946 against Maharaja Hari Singh.", "He was arrested soon after the movement began.", [4372]),
(S, "How many Prime Ministers did Pakistan have between 1947 and 1958?", ["5", "6", "8", "7"], 3, "They were Liaquat Ali Khan, Khawaja Nazimuddin, Mohammad Ali Bogra, Chaudhry Mohammad Ali, H. S. Suhrawardy, I. I. Chundrigar and Feroz Khan Noon, which makes 7.", "Martial law was imposed in October 1958 by Iskander Mirza and Ayub Khan.", [1872, 1877, 3555]),
]
